Scripts.OnUpdate:
if this.mouseInside then
	if IsShiftKeyDown() == 1 then
		GameTooltip:SetOwner(this, "ANCHOR_LEFT");
		GameTooltip:ClearLines()
		GameTooltip:AddLine(this.path,1,0.8196079,0);
		GameTooltip:Show()
		this.UpdateTooltip = nil;
	else
		GameTooltip:Hide();
	end
end

Scripts.OnMouseWheel:
local bar = getglobal(this:GetParent():GetName().."ScrollBar");
this = bar;
local val = max((FauxScrollFrame_GetOffset(bar) - arg1)*16,0);
local _,m = _G[bar:GetName().."ScrollBar"]:GetMinMaxValues();
val = min(val,m);

local scrollBar = getglobal(this:GetName().."ScrollBar");
	scrollBar:SetValue(val);
	this.offset = floor((val / 16) + 0.5);
	local updateFunction = this:GetScript("OnShow");
	if updateFunction then updateFunction(); end

Scripts.OnLoad:
   UIDropDownMenu_Initialize(this, function()
		for i = 1,table.getn(GHM_IconCategories) do
			info            = {};
			info.text       = GHM_IconCategories[i];
			info.value      = i;
			info.owner		= this:GetParent():GetParent();
			info.func       = function()

				this.owner.IconCatagory = this.value;
				this.owner.IconSubcatagory = 1;
				getglobal(this.owner:GetName().."CatagoryTextLabel"):SetText(GHM_IconCategories[this.value]);
				getglobal(this.owner:GetName().."SubcatagoryTextLabel"):SetText(GHM_IconSubcategories[GHM_IconCategories[this.value]][this.owner.IconSubcatagory]);
				getglobal(this.owner:GetName().."ScrollBar"):SetVerticalScroll(1);
				getglobal(this.owner:GetName().."ScrollBar"):SetVerticalScroll(0);
			end;
			UIDropDownMenu_AddButton(info);
		end	
	end);
    getglobal(this:GetName().."TextLabel"):SetText(GHM_IconCategories[1]);

   UIDropDownMenu_Initialize(this, function()
		local IconCatagory
		local owner = this:GetParent():GetParent();
		if not(owner.IconCatagory) then owner.IconCatagory = 1; end
		for i = 1,table.getn(GHM_IconSubcategories[GHM_IconCategories[owner.IconCatagory]]) do
			info            = {};
			info.text       = GHM_IconSubcategories[GHM_IconCategories[owner.IconCatagory]][i];
			info.value      = i;
			info.owner		= this:GetParent():GetParent();
			info.func       = function()

				this.owner.IconSubcatagory = this.value;
				getglobal(this.owner:GetName().."SubcatagoryTextLabel"):SetText(GHM_IconSubcategories[GHM_IconCategories[owner.IconCatagory]][this.value]);
				getglobal(this.owner:GetName().."ScrollBar"):SetVerticalScroll(1);
				getglobal(this.owner:GetName().."ScrollBar"):SetVerticalScroll(0);	
			end;
			UIDropDownMenu_AddButton(info);
		end	
	end);
    getglobal(this:GetName().."TextLabel"):SetText(GHM_IconSubcategories[GHM_IconCategories[1]][1]);

Scripts.OnShow:
local scrollFrame = this;
local owner = this:GetParent();
if not(owner.IconCatagory) then
	owner.IconCatagory = 1;
end
if not(owner.IconSubcatagory) then
	owner.IconSubcatagory = 1;
end
local category = tostring(GHM_IconSubcategories[ GHM_IconCategories[owner.IconCatagory]][owner.IconSubcatagory]); --GHI_IconCatagory] ][GHI_IconSubcatagory]);

if catagory == "" then return; end	
local lines = floor(((table.getn(GHM_StockIcons[ category  ])+1) / 4)+0.5)-3;
if lines == nil then return; end
FauxScrollFrame_Update(scrollFrame,lines,1,16);	
local offset = FauxScrollFrame_GetOffset(scrollFrame);

local iconFrame = this:GetParent();
for i=1,16 do 

	local frame = getglobal(iconFrame:GetName().."_PopupButton"..i);
	local texture = GHM_StockIcons[category][offset*4 + i];
	if texture == nil then
		SetItemButtonTexture(frame, "");
		frame.path = "";
	else
		SetItemButtonTexture(frame, "Interface\\Icons\\"..texture);
		frame.path = "Interface\\Icons\\"..texture;
	end
end

