	this.main.SetLabel(this.label,this.val);										
end

Scripts.OnLoad:
local f = this;
f.Force = function(data)
	--GHI_Message("Check button forced to "..(data or btype(data)));
	if data == true or data == 1 then
		f:SetChecked(true);
	else 
		f:SetChecked(nil);
	end
end
f.Clear = function()
	f:SetChecked(nil);
	f.main.SetLabel(f.label,nil);
end

local f = this;
f.Force = function(data)
	local label2 = getglobal(f:GetName().."TextLabel");
	if type(data) == "number" then
		local color = ITEM_QUALITY_COLORS[data];
		if color then
			label2:SetText("|CFF" ..string.format("%.2x",color.r*255) .. string.format("%.2x",color.g*255) .. string.format("%.2x",color.b*255) .." "..getglobal("ITEM_QUALITY"..data.."_DESC").."|r"); 
			f.main.SetLabel(f.label,data);
		end
	end

end
f.Clear = function()
	local label2 = getglobal(f:GetName().."TextLabel");
	local color = ITEM_QUALITY_COLORS[1];
	if color then
		label2:SetText("|CFF" ..string.format("%.2x",color.r*255) .. string.format("%.2x",color.g*255) .. string.format("%.2x",color.b*255) .." "..getglobal("ITEM_QUALITY1_DESC").."|r"); 
		f.main.SetLabel(f.label,1);
