UIDropDownMenu_Initialize(this, function()
	for i = 0,6 do	
		info            = {};
		local text = getglobal("ITEM_QUALITY" .. i .. "_DESC");
		local color = ITEM_QUALITY_COLORS[i];
		info.text       = "|CFF" ..string.format("%.2x",color.r*255) .. string.format("%.2x",color.g*255) .. string.format("%.2x",color.b*255) .." ".. text.."|r";
		info.value      = i;
		info.owner		= this:GetParent();
		info.func       = function()
							local color = ITEM_QUALITY_COLORS[this.value];
							getglobal( (this.owner):GetName().."TextLabel"):SetText("|CFF" ..string.format("%.2x",color.r*255) .. string.format("%.2x",color.g*255) .. string.format("%.2x",color.b*255) .." "..getglobal("ITEM_QUALITY" ..this.value.. "_DESC").."|r"); 
							this.owner.main.SetLabel(this.owner.label,this.value);	
						end;
		UIDropDownMenu_AddButton(info);
	end	

end);

-- Turtle/Vanilla UIDropDownMenu has a small fixed button pool.
-- Keep CustomDD menus at eight entries per level and split larger
-- lists into range submenus. Capture the dropdown frame so submenu
-- callbacks do not depend on the global `this` value.
local f = this;
f.dataTable = f:GetParent().tempdata;
UIDropDownMenu_Initialize(f, function(level)
	local t = f.dataTable;
	if type(t) == "table" then
		local pageSize = 8;
		if type(UIDROPDOWNMENU_MAXBUTTONS) == "number" and pageSize > UIDROPDOWNMENU_MAXBUTTONS then
			pageSize = UIDROPDOWNMENU_MAXBUTTONS;
		end
		if not(level) then
			level = 1;
		end

		local function AddChoice(i,menuLevel)
			local info = {};
			info.text = t[i];
			info.value = i;
			info.owner = f;
			info.func = function()
				local text = this.owner.dataTable[this.value];
				getglobal((this.owner):GetName().."TextLabel"):SetText(text);
				if this.owner.returnIndex == true then
					this.owner.main.SetLabel(this.owner.label,this.value);
				else
					this.owner.main.SetLabel(this.owner.label,text);
				end
			end;
			UIDropDownMenu_AddButton(info,menuLevel);
		end

		local count = table.getn(t);
		if count > pageSize then
			if level == 1 then
				local startIndex = 1;
				while count >= startIndex do
					local endIndex = startIndex + pageSize - 1;
					if endIndex > count then
						endIndex = count;
					end
					local info = {};
					info.text = t[startIndex].." - "..t[endIndex];
					info.value = { ghmStart = startIndex, ghmEnd = endIndex };
					info.hasArrow = true;
					info.notCheckable = true;
					UIDropDownMenu_AddButton(info,1);
					startIndex = endIndex + 1;
				end
			elseif level == 2 then
				local range = UIDROPDOWNMENU_MENU_VALUE;
				if type(range) == "table" and type(range.ghmStart) == "number" and type(range.ghmEnd) == "number" then
					for i = range.ghmStart,range.ghmEnd do
						AddChoice(i,2);
					end
				end
			end
		else
			for i = 1,count do
				AddChoice(i,level);
			end
		end
	end
end);
f.Force = function(data)
	local label = getglobal(f:GetName().."TextLabel");
	if type(data) == "number" then
		local text = f.dataTable[data];
		if text then
			label:SetText(text); 
			if f.returnIndex == true then
				f.main.SetLabel(f.label,data);
			else
				f.main.SetLabel(f.label,text);
			end
		end
	elseif type(data) == "string" then
		for i = 1,table.getn(f.dataTable) do
			if data == f.dataTable[i] then
				label:SetText(data); 
				if f.returnIndex == true then
					f.main.SetLabel(f.label,i);
				else
					f.main.SetLabel(f.label,data);
				end
			end
		end
	end
end
f.Clear = function()
	local label = getglobal(f:GetName().."TextLabel");

	local text = f.dataTable[1];
	if text then
		label:SetText(text); 
		if f.returnIndex == true then
			f.main.SetLabel(f.label,1);
		else
			f.main.SetLabel(f.label,text);
		end
	end

end

Scripts.OnClick:
local main = this.main;
if not(main.iconFrame) then
	main.iconFrame = CreateFrame("Frame",main:GetName().."_IconFrame",this,"GHM_IconFrame_Template");
end
local frame = main.iconFrame;
frame.from = this;
if this.framealign == "l" then
	frame:SetPoint("RIGHT", main, "LEFT", 0, 0);
elseif this.framealign == "r" then
	frame:SetPoint("LEFT", main, "RIGHT", 0, 0);
else
	frame:SetPoint("CENTER", main, "CENTER", 0, 0);
	frame:SetFrameLevel(this:GetFrameLevel()+10);
end
frame:Show();

Scripts.OnLoad:
SetItemButtonTexture(this, "Interface\\Icons\\INV_Misc_QuestionMark");
this.IconChoosen = function(orig,icon)

	-- Keep the exact icon path as data.  On Turtle/Vanilla the
	-- texture object's GetTexture() result is not a reliable place
	-- to recover the original path later.
	orig.selectedPath = icon.path;
	SetItemButtonTexture(orig,icon.path);
	orig.main.SetLabel(orig.label,icon.path);
	if orig.CloseOnChoosen == true then
		icon:GetParent():Hide();
	end
end
local f = this;
f.Force = function(data)
	f.selectedPath = data;
	SetItemButtonTexture(f,data);
	f.main.SetLabel(f.label,data);
end
f.Clear = function()

	f.selectedPath = "Interface\\Icons\\INV_Misc_QuestionMark";
	SetItemButtonTexture(f, "Interface\\Icons\\INV_Misc_QuestionMark");
	f.main.SetLabel(f.label,"Interface\\Icons\\INV_Misc_QuestionMark");
end

local f = this;
f.Force = function(data)
	if type(data) == "string" then
		getglobal(f:GetName().."ScrollText"):SetText(data);
	end
end
f.Clear = function()

	getglobal(f:GetName().."ScrollText"):SetText("");
end

