Scripts.OnCursorChanged:
	local scrollBar = getglobal(this:GetParent():GetName().."ScrollBar")
	local h = scrollBar:GetHeight();

	if (-arg2)-h-scrollBar:GetValue() > 22 then
		scrollBar:SetValue(-arg2+ (-3.0*arg3) -h);
	end
    if -3 > -arg2-scrollBar:GetValue() then
		scrollBar:SetValue(-arg2- 1.5*arg3);
	end

Scripts.OnLoad:
local f = this;
f.images = {};
f.numFramesCreated = 0;
f.selected = 0;
f.scaleX = 1
f.scaleY = 1
f.Force = function(data) -- select one with specific path
	if type(data) == "string" or type(data)== "number" then
		for i,img in pairs(f.images) do
			local imgF = getglobal(f:GetName().."Img"..i);
			if imgF then
				if type(img)=="table" and (img.p == data or i==data) then
					-- select number x
					imgF:SetChecked(true);
				else
					-- else hide
					imgF:SetChecked(nil);
				end
			end
		end
	end
end
f.Clear = function()
	-- clear selection
	f.selected = 0;
	for i=1,f.numFramesCreated do
		getglobal(f:GetName().."Img"..i):SetChecked(nil);
	end
end

f.SetScale = function(x,y) assert(type(x)=="number" and type(y)=="number","Scale must be a number")
	f.scaleX = x;
	f.scaleY = y;
	f.SetImages(f.images)
end

f.SetImages = function(imgList) --print("Total of ",table.getn(imgList))
	local scroll = getglobal(f:GetName().."ScrollChildFrame");

	scroll:SetWidth(f:GetWidth());

	local numPrLine = floor(f:GetWidth()/((74*f.scaleX)));
	if numPrLine*74*f.scaleX +(numPrLine-1)*10 > f:GetWidth() then
		numPrLine = numPrLine-1;
	end
	--local numLines = ceil(table.getn(imgList)/numPrLine)	
	--print(numPrLine," pr line")
	--scroll:SetHeight((numLines*(74))) --+10))-10);	

	f.images = imgList;

	for i=1,table.getn(imgList) do --print("Creating img ",i)
		local imgF;
		local x,y,p = imgList[i].x or 256,imgList[i].y or 256,imgList[i].p or "";
		if f.numFramesCreated >= i then
			imgF = getglobal(f:GetName().."Img"..i);
		else 
			imgF = CreateFrame("CheckButton",f:GetName().."Img"..i,scroll,"GHM_ImageButton_Template"); --
			imgF.i = i;
			imgF.f = f;
			f.numFramesCreated = i;
		end

		imgF:SetChecked(false);

		local icon = _G[imgF:GetName().."IconTexture"];
		icon:SetTexture(p);
		imgF.path = p;

		--local scale = max(x,y)/128;			
		local scale = max(x/(128*f.scaleX),y/(128*f.scaleY))
		icon:SetWidth((x/ scale * (37/64)));
		icon:SetHeight((y/ scale * (37/64)));	

		imgF:SetWidth(74*f.scaleX);
		imgF:SetHeight(74*f.scaleY);
		getglobal(imgF:GetName().."NormalTexture"):SetWidth(128*f.scaleX)
		getglobal(imgF:GetName().."NormalTexture"):SetHeight(128*f.scaleY)

		imgF:ClearAllPoints()
		if i == 1 then --print("first");
			imgF:SetPoint("TOPLEFT",scroll, "TOPLEFT", 0, 0);
		elseif mod(i,numPrLine) == 1 then --print("new line");
			imgF:SetPoint("TOP",getglobal(f:GetName().."Img"..(i-numPrLine)), "BOTTOM", 0, -10);
		else --print("next");
			imgF:SetPoint("LEFT",getglobal(f:GetName().."Img"..(i-1)), "RIGHT", 10, 0);
		end



		imgF:Show();
		prevImgF = imgF
	end
	for i = table.getn(imgList)+1,f.numFramesCreated do
		local pf = getglobal(f:GetName().."Img"..i)
		if pf then pf:Hide() end
	end
end
